function makePixelRegion(layer,snapshot,mask,bounds,cropped=false){
 const region=bounds?{board:h.board,layerId:layer.id,snapshot,mask,bounds}:null;
 if(cropped&&region)region.remainingFactory=()=>remainingRegionTiles(layer,region,(l,rect)=>renderer.snapshotRegion(l,rect));
 return region;
}
function pickLassoRegion(polygon){try{
 const l=editable(h.board);if(maskTarget)throw Error('Choose Edit artwork before selecting pixels');if(!layerState(h.board,l).visible)throw Error('Active layer is hidden');const anchor=l.strokes[0]?.points[0];if(!anchor)throw Error('Active layer is empty');
 const window=polygonWindow(polygon);let cropped=false,snapshot=l.strokes.length===1?nativePixelSnapshot(l.strokes[0]):null;
 if(!snapshot){try{snapshot=renderer.snapshotLayer(l,0,anchor);}catch(e){if(!e.message.startsWith('Smudge layer exceeds'))throw e;cropped=true;snapshot=renderer.snapshotRegion(l,window);}}
 if(snapshot&&(snapshot.width>1024||snapshot.height>1024)){cropped=true;snapshot=renderer.snapshotRegion(l,window);}if(!snapshot)throw Error('Active layer is empty');const {mask,bounds}=polygonPixels(snapshot,polygon);
 const region=makePixelRegion(l,snapshot,mask,bounds,cropped);
 wandRegion=region;wandImage=null;selected=[];layerScope=[l.id];scopeBoard=h.board.id;scopeActive=l.id;status(bounds?bounds.count.toLocaleString()+' pixels selected · drag highlighted pixels, then Apply':'No layer pixels inside lasso');return !!bounds;
 }catch(e){status(e.message.replace('Smudge layer','Region lasso layer')+' · prior selection retained',true);return false;}}

async function pasteImageFile(file){
 if(blocked()||!h)return;const base=h.board;busy=true;status('Reading clipboard image…');try{const decoded=await decodeImageFile(file);if(h.board!==base)throw Error('Artwork changed; paste again');const center=toDocument(canvas.clientWidth/2,canvas.clientHeight/2,view),stroke=rasterStroke(decoded.data,decoded.width,decoded.height,center.x-decoded.width/2,center.y-decoded.height/2);let layerId;const next=command(h,b=>{layerId=mutateImage(b,stroke,'Pasted image');});wandRegion=null;changed(next,true);selected=[stroke.id];layerScope=[layerId];scopeBoard=h.board.id;scopeActive=layerId;clipboard=copySelection(h.board,selected,scope());status('Clipboard image pasted on a new layer · Undo restores artwork');}catch(e){status('Clipboard image not pasted · '+e.message,true);}finally{busy=false;refresh();}
}
async function readClipboardImage(){if(blocked())return;try{if(!navigator.clipboard?.read)throw Error('Use Ctrl+V or Import image');const items=await navigator.clipboard.read();for(const item of items){const type=item.types.find(t=>['image/png','image/jpeg'].includes(t));if(type){const blob=await item.getType(type);await pasteImageFile(new File([blob],type==='image/png'?'clipboard.png':'clipboard.jpg',{type}));return;}}status('Clipboard has no PNG/JPEG image · copy artwork or use Import image',true);}catch(e){status('Clipboard access unavailable · use Ctrl+V or Import image',true);}}
$('clipboard-image-paste').onclick=readClipboardImage;
window.addEventListener('paste',e=>{if(e.target.closest?.('input,textarea,[contenteditable="true"]')||blocked())return;const file=[...(e.clipboardData?.files||[])].find(f=>['image/png','image/jpeg'].includes(f.type));if(file){e.preventDefault();pasteImageFile(file);}else if(clipboard){e.preventDefault();selectionAction('paste');}else status('Clipboard has no artwork or image to paste',true);});
function clipboardPixels(payload){if(payload.strokes.length===1){const native=nativePixelSnapshot(payload.strokes[0]);if(native)return native;}const first=payload.strokes[0]?.points[0];if(!first)throw Error('Nothing selected');const snap=renderer.snapshotLayer({strokes:payload.strokes},0,first);if(!snap)throw Error('Selection has no visible pixels');return snap;}
function copyImageToSystem(payload){const prefix=wandRegion?'Pixel region copied · page clipboard':'Copied '+payload.strokes.length+' strokes · page clipboard';status(prefix+' · writing PNG image');try{const snapshot=clipboardPixels(payload);writeImage(snapshot).then(()=>status(prefix+' · Copied as PNG image · paste into another app')).catch(()=>status(prefix+' · browser blocked image clipboard; use Download selection PNG',true));}catch(e){status(prefix+' · '+e.message+'; use Download selection PNG',true);}}
$('download-selection').onclick=()=>{if(blocked())return;try{const payload=wandRegion?regionClipboard(h,targetRegion()):copySelection(h.board,selected,scope());downloadImage(clipboardPixels(payload)).then(()=>status('Selection PNG downloaded')).catch(e=>status(e.message,true));}catch(e){status(e.message,true);}};

pathEditor=initPathSelection({$,canvas,getState:()=>({board:h?.board,layerId:h?.board.activeLayer,view:{...view},magnetic:lassoMode==='magnetic',enabled:['path','magnetic'].includes(lassoMode)&&['lasso','move','pan'].includes(tool),space:space||tool==='pan',preview:!!pending||!!active,blocked:blocked(),writable:!!h&&!maskTarget&&!layerState(h.board,h.board.layers.find(l=>l.id===h.board.activeLayer)).locked&&layerState(h.board,h.board.layers.find(l=>l.id===h.board.activeLayer)).visible,inside:insideSelection}),onBegin:()=>{const prior={selected:[...selected],region:wandRegion,layerScope:[...layerScope],scopeBoard,scopeActive};selected=[];wandRegion=null;wandImage=null;layerScope=[h.board.activeLayer];scopeBoard=h.board.id;scopeActive=h.board.activeLayer;return prior;},onCancel:prior=>{selected=prior.selected;wandRegion=prior.region;wandImage=null;layerScope=prior.layerScope;scopeBoard=prior.scopeBoard;scopeActive=prior.scopeActive;},onSelect:polygon=>pickLassoRegion(polygon),onSnap:(p,scale)=>snapEdge(renderer.snapshotRegion(editable(h.board),magneticWindow(p,scale)),p,magneticRadius(scale)).point,onChange:refresh,status});

$('bucket').onclick=()=>{if(blocked())return;const same=tool==='bucket';setTool('bucket');togglePopover('bucket-controls','bucket',same);refresh();status('Bucket · sample the chosen reference; fill the active layer inside your selection or an enclosed area');};
$('bucket-close').onclick=()=>{closePopovers();canvas.focus();};
function bucketFill(done){try{
 if(done.base!==h.board||done.layerId!==h.board.activeLayer)throw Error('Fill target changed · artwork unchanged');
 const layer=editable(h.board);if(!layerState(h.board,layer).visible)throw Error('Fill layer is hidden');
 if(done.fillConfig.opacity===0){status('Fill opacity is 0% · artwork unchanged');return;}
 const rect=wandRegion?{x:wandRegion.snapshot.x,y:wandRegion.snapshot.y,width:wandRegion.snapshot.width,height:wandRegion.snapshot.height}:bucketWindow(done.bucketPoint),snapshot=wandRegion?targetRegion().snapshot:renderer.snapshotRegion(layer,rect),reference=sampleArea(rect,layer,$('fill-reference').value);let found;if(wandRegion){const r=wandRegion.snapshot,mask=new Uint8Array(rect.width*rect.height);for(let y=0;y<rect.height;y++)for(let x=0;x<rect.width;x++){const xx=rect.x+x-r.x,yy=rect.y+y-r.y;if(xx>=0&&yy>=0&&xx<r.width&&yy<r.height)mask[y*rect.width+x]=wandRegion.mask[yy*r.width+xx];}found={mask};}else found=bucketMask(reference,Math.floor(done.bucketPoint.x-reference.x),Math.floor(done.bucketPoint.y-reference.y),done.fillConfig);const paint=fillPixels(snapshot,found.mask,{...done.fillConfig,alphaLock:!!layer.alphaLock});
 if(!paint.changed){status('No fill change · same colour or alpha-locked transparent area');return;}
 if(snapshot.id)paint.stroke.id=snapshot.id;const region={snapshot,mask:found.mask},next=commitBucket(h,done.base,done.layerId,paint,()=>remainingRegionTiles(layer,region,(l,rect)=>renderer.snapshotRegion(l,rect)));
 changed(next,true);status(paint.count.toLocaleString()+' pixels filled · active layer · Undo restores original artwork');
 }catch(e){status(e.message,true);refresh();}}

function commitAreaFill(board,layer,snapshot,mask,paint){
 if(!paint.changed){status('No fill change · same paint, 0% opacity or alpha lock');return;}
 if(snapshot.id)paint.stroke.id=snapshot.id;const region={snapshot,mask},next=commitBucket(h,board,layer.id,paint,()=>remainingRegionTiles(layer,region,(l,rect)=>renderer.snapshotRegion(l,rect)));
 changed(next,true);status(paint.count.toLocaleString()+' pixels filled · active layer · Undo restores original artwork');
}
function encloseFill(done){try{
 if(done.fillBoard!==h.board||done.fillLayer!==h.board.activeLayer)throw Error('Enclose target changed · artwork unchanged');
 if(maskTarget)throw Error('Choose Edit artwork before filling pixels');const layer=editable(h.board);if(!layerState(h.board,layer).visible)throw Error('Fill layer is hidden');
 const snapshot=renderer.snapshotRegion(layer,encloseWindow(done.polygon)),{mask,paint}=prepareEnclose(snapshot,done.polygon,{...done.fillConfig,alphaLock:!!layer.alphaLock});
 commitAreaFill(done.fillBoard,layer,snapshot,mask,paint);
 }catch(e){status(e.message+' · artwork unchanged',true);refresh();}}
$('fill-selection').onclick=()=>{if(blocked()||pathEditor?.editing())return;try{
 if(maskTarget)throw Error('Choose Edit artwork before filling pixels');const region=targetRegion();
 const layer=editable(h.board);if(!layerState(h.board,layer).visible)throw Error('Fill layer is hidden');const paint=fillPixels(region.snapshot,region.mask,{color:settings.color,opacity:settings.opacity,alphaLock:!!layer.alphaLock});
 commitAreaFill(h.board,layer,region.snapshot,region.mask,paint);
 }catch(e){status(e.message+' · artwork unchanged',true);refresh();}};

// One disposable raster target for every selection mode; original history stays untouched.
function prepareDeformation(){
 if(maskTarget)throw Error('Choose Edit artwork before deformation');
 if(pathEditor?.editing()){if(!pathEditor.hasPoints())pathEditor.cancel(false);else if(!pathEditor.close())throw Error('Finish a closed selection outline before deformation');}
 const original=h.board,l=editable(original);let base=original,id;
 if(wandRegion){const prepared=prepareRegionTransform(h,targetRegion());base=prepared.working.board;id=prepared.id;}
 else{
  const ids=selected.length?[...selected]:l.strokes.map(s=>s.id);
  if(!ids.length)throw Error('Active layer is empty · add artwork before deformation');
  const items=ids.map(id=>l.strokes.find(s=>s.id===id));if(items.some(s=>!s))throw Error('Select artwork on the active layer before deformation');
  if(items.length===1&&items[0].brush==='raster')id=items[0].id;
  else{
   const snapshot=renderer.snapshotLayer({...l,strokes:items},0,items[0].points[0]);if(!snapshot||!snapshot.data.some((v,i)=>i%4===3&&v))throw Error('Selected artwork has no visible pixels');
   const stroke=rasterStroke(snapshot.data,snapshot.width,snapshot.height,snapshot.x,snapshot.y);if(items.every(s=>s.guide))stroke.guide={version:1,kind:'image'};
   base=structuredClone(original);base.version=Math.max(4,base.version);const layer=base.layers.find(t=>t.id===l.id),last=Math.max(...ids.map(id=>layer.strokes.findIndex(s=>s.id===id)));layer.strokes=layer.strokes.flatMap((s,i)=>i===last?[stroke]:ids.includes(s.id)?[]:[s]);id=stroke.id;
  }
 }
 const source=warpTarget(base,l.id,id);return {original,base,layerId:l.id,id,source:structuredClone(source)};
}
function commitDeformation(layerId,id,stroke,original,working){
 if(h.board!==original)throw Error('Deformation is stale');const l=editable(original),state=layerState(original,l);if(l.id!==layerId||state.locked||!state.visible||l.alphaLock)throw Error('Deformation layer is not writable');
 const layer=working.layers.find(l=>l.id===layerId),source=layer.strokes.find(s=>s.id===id);if(JSON.stringify(stroke)===JSON.stringify(source))return;
 const strokes=layer.strokes.map(s=>s.id===id?stroke:s);const next=command(h,b=>{b.version=Math.max(4,b.version);b.layers.find(l=>l.id===layerId).strokes=structuredClone(strokes);});changed(next,true);wandRegion=null;wandImage=null;pathEditor?.cancel(false);selected=[id];refresh();
}

